<script setup>
import { onBeforeUnmount, ref, watch } from 'vue'
import { api, fileUrl, Tags } from '../api'
import TagPicker from './TagPicker.vue'
const props=defineProps({worldId:Number})
const page=ref({items:[],total:0}),selected=ref([]),labels=ref([]),globals=ref([]),q=ref(''),kind=ref(''),label=ref(''),tag=ref(''),offset=ref(0),detail=ref(null),error=ref(''),runs=ref([])
const name=ref(''),alias=ref(''),parent=ref(''),editingLabel=ref('')
const referenceKind=ref('character'),referenceId=ref(''),allowCross=ref(false)
const prefs=ref({favorite:false,stars:0,preference:0,notes:'',global_tag_ids:[],label_ids:[]})
let disposed=false,sequence=0
const dirty=new Set()
function mark(key){dirty.add(key)}
onBeforeUnmount(()=>{disposed=true;sequence++})
async function load(){const n=++sequence;try{const data=await api.get(`/api/worlds/${props.worldId}/archive`,{q:q.value,kind:kind.value,label_id:label.value,tag_id:tag.value,offset:offset.value,limit:50});if(!disposed&&n===sequence)page.value=data}catch(e){error.value=e.message}}
async function init(){selected.value=[];detail.value=null;offset.value=0;labels.value=await api.get(`/api/worlds/${props.worldId}/labels`);globals.value=(await Tags.list({limit:500})).items;runs.value=await api.get('/api/project-imports',{world_id:props.worldId});await load()}
watch(()=>props.worldId,init,{immediate:true})
async function inspect(row){try{detail.value=await api.get(`/api/worlds/${props.worldId}/archive/${row.id}`);prefs.value={favorite:row.favorite,stars:row.stars,preference:row.preference,notes:row.notes,global_tag_ids:[...row.global_tag_ids],label_ids:[...row.label_ids]};selected.value=[row.id];dirty.clear()}catch(e){error.value=e.message}}
async function save(){if(!dirty.size){error.value='请先修改要保存的字段';return}try{const patch=Object.fromEntries([...dirty].map(k=>[k,prefs.value[k]]));await api.patch(`/api/worlds/${props.worldId}/archive`,{ids:selected.value,...patch});dirty.clear();await load();error.value=''}catch(e){error.value=e.message}}
async function saveLabel(){try{const body={name:name.value,aliases:alias.value.split(/[、,，]/).map(x=>x.trim()).filter(Boolean),parent_id:parent.value?Number(parent.value):null};if(editingLabel.value)await api.put(`/api/worlds/${props.worldId}/labels/${editingLabel.value}`,body);else await api.post(`/api/worlds/${props.worldId}/labels`,body);labels.value=await api.get(`/api/worlds/${props.worldId}/labels`);name.value='';alias.value='';parent.value='';editingLabel.value=''}catch(e){error.value=e.message}}
function editLabel(id){const row=labels.value.find(l=>l.id===Number(id));if(row){name.value=row.name;alias.value=row.aliases.join('、');parent.value=row.parent_id||''}else{name.value='';alias.value='';parent.value=''}}
async function sync(){try{await api.post(`/api/worlds/${props.worldId}/archive/sync`);await load()}catch(e){error.value=e.message}}
async function addRef(){try{await api.post(`/api/worlds/${props.worldId}/archive/references`,{entity_kind:referenceKind.value,entity_id:Number(referenceId.value),allow_cross_world:allowCross.value});await load()}catch(e){error.value=e.message}}
async function remove(){if(!confirm('仅移除此世界观中的引用？原资料和源文件会保留。'))return;try{await api.del(`/api/worlds/${props.worldId}/archive/${detail.value.id}`);detail.value=null;selected.value=[];await load()}catch(e){error.value=e.message}}
function link(row){return {asset:`/assets?open=${row.entity_id}`,character:`/characters/${row.entity_id}`,entry:`/worlds?entry=${row.entity_id}`,note:`/notes/${row.entity_id}`,work:`/works?id=${row.entity_id}`,relation:'/graph'}[row.entity_kind]}
</script>
<template>
<div class="grid">
<p v-if="error" role="alert" class="notice">{{error}}</p>
<div class="row"><RouterLink class="btn primary" :to="{path:'/project-preview',query:{world_id:worldId}}">预览并导入项目</RouterLink><button @click="sync">归档本世界已有条目引用</button><span class="small muted">引用不复制原文件，不合并同名人物。</span></div>
<form class="archive-search" @submit.prevent="offset=0;load()"><label class="field">世界观内搜索<input v-model="q" placeholder="标题、正文、设定或备注"/></label><select v-model="kind" aria-label="资料类型"><option value="">所有类型</option><option v-for="(v,k) in {asset:'素材',character:'人物',entry:'设定条目',note:'笔记',work:'作品',relation:'关系'}" :key="k" :value="k">{{v}}</option></select><select v-model="label" aria-label="局部标签筛选"><option value="">全部局部标签</option><option v-for="l in labels" :key="l.id" :value="l.id">{{l.name}} {{l.aliases.join('/')}}</option></select><select v-model="tag" aria-label="全局标签筛选"><option value="">全部全局标签</option><option v-for="t in globals" :key="t.id" :value="t.id">{{t.name}}</option></select><button>筛选</button></form>
<div class="archive-grid">
<section class="card grid"><div class="row"><b>{{page.total}} 项 · 已选 {{selected.length}}</b><button @click="selected=page.items.map(r=>r.id)">选择本页</button></div><div class="archive-table"><table><thead><tr><th>选择</th><th>档案</th><th>评分</th></tr></thead><tbody><tr v-for="row in page.items" :key="row.id"><td><input v-model="selected" type="checkbox" :value="row.id"/></td><td><button @click="inspect(row)">{{row.title}}</button><small class="muted">{{row.entity_kind}} · {{row.category}} · {{row.storage_mode}} {{row.missing_record?'原记录已移除':''}}</small></td><td>{{row.favorite?'★':''}} {{row.stars}}星 / {{row.preference}}</td></tr></tbody></table></div><nav class="row"><button :disabled="!offset" @click="offset-=50;load()">上一页</button><span>{{Math.floor(offset/50)+1}} / {{Math.max(1,Math.ceil(page.total/50))}}</span><button :disabled="offset+50>=page.total" @click="offset+=50;load()">下一页</button></nav></section>
<section class="card grid"><h2 style="margin:0">{{selected.length>1?'批量管理':detail?.title||'选择资料'}}</h2><template v-if="selected.length"><label class="row"><input v-model="prefs.favorite" @change="mark('favorite')" type="checkbox" style="width:auto"/>收藏</label><div class="grid cols-2"><label class="field">星级<input v-model.number="prefs.stars" @input="mark('stars')" type="number" min="0" max="5"/></label><label class="field">喜爱度<input v-model.number="prefs.preference" @input="mark('preference')" type="number" min="0" max="100"/></label></div><label class="field">备注<textarea v-model="prefs.notes" @input="mark('notes')"/></label><details><summary>全局标签</summary><TagPicker v-model="prefs.global_tag_ids" @update:model-value="mark('global_tag_ids')"/></details><div class="row"><label v-for="l in labels" :key="l.id" class="row small"><input v-model="prefs.label_ids" @change="mark('label_ids')" type="checkbox" :value="l.id" style="width:auto"/>{{l.name}}</label></div><button class="primary" @click="save">保存所选档案的偏好与标签</button></template><template v-if="detail && selected.length===1"><p v-if="detail.file_status && detail.file_status!=='ok'" role="alert" class="notice">{{detail.file_status}}</p><p class="mono muted">{{detail.source_path}}</p><pre v-if="detail.content">{{detail.content.slice(0,4000)}}</pre><div class="row"><RouterLink class="btn" :to="link(detail)">打开原资料</RouterLink><a v-if="detail.asset_id" class="btn" :href="fileUrl(detail.asset_id)" download>下载原文件</a><button class="danger" @click="remove">移除本世界引用</button></div></template></section>
</div>
<details class="card"><summary>世界观局部标签：层级与别名</summary><form class="grid" @submit.prevent="saveLabel"><label class="field">编辑标签<select v-model="editingLabel" @change="editLabel(editingLabel)"><option value="">新建局部标签</option><option v-for="l in labels" :key="l.id" :value="l.id">{{l.name}} · #{{l.id}}</option></select></label><div class="grid cols-2"><label class="field">标签名称<input v-model="name" required maxlength="80"/></label><label class="field">别名（逗号分隔）<input v-model="alias"/></label></div><label class="field">父标签<select v-model="parent"><option value="">根标签</option><option v-for="l in labels" :key="l.id" :value="l.id">{{l.name}}</option></select></label><button>保存局部标签</button></form></details>
<details class="card"><summary>明确引用已有资料</summary><form class="row" @submit.prevent="addRef"><select v-model="referenceKind" aria-label="引用类型"><option v-for="k in ['asset','character','entry','note','work','relation']" :key="k">{{k}}</option></select><input v-model="referenceId" type="number" min="1" aria-label="资料ID" required/><label class="row"><input v-model="allowCross" type="checkbox" style="width:auto"/>明确允许跨世界观引用</label><button>添加引用</button></form></details>
<details class="card"><summary>持久导入批次与恢复</summary><div v-for="run in runs" :key="run.id" class="row"><span>{{run.id}} · {{run.mode}} · {{run.status}}</span><RouterLink class="btn" :to="{path:'/project-preview',query:{world_id:worldId,import_id:run.id}}">查看或恢复</RouterLink></div></details>
</div>
</template>
<style scoped>.archive-search{display:grid;grid-template-columns:minmax(130px,1fr) repeat(3,minmax(90px,140px)) auto;gap:8px;align-items:end}.archive-search>*{min-width:0}@media(max-width:800px){.archive-search{grid-template-columns:minmax(0,1fr)}}.archive-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:12px;align-items:start}.archive-grid>*{min-width:0}.archive-table{max-height:530px;overflow:auto}td small{display:block}td button{white-space:normal;text-align:left}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:330px;overflow:auto;font-size:12px}summary{cursor:pointer}@media(max-width:1100px){.archive-grid{grid-template-columns:minmax(0,1fr)}}</style>
